package com.mg.fixturecockpitsim;
import android.content.Context;import android.graphics.*;import android.view.View;import java.util.Locale;
/** AVM-10.7 world: deeper hangar, realistic airport settlement, RWY27 and coast/sea transition. */
public final class RunwayHudView extends View{
 private final Paint f=new Paint(3),l=new Paint(3);private final Path p=new Path();private volatile float altitudeM,speedMps,route,groundProgress,headingDeg;private volatile boolean onGround,demoMode;private volatile String phase="";private float scroll,runwayMeters;private long last;
 public RunwayHudView(Context c){super(c);f.setStyle(Paint.Style.FILL);l.setStyle(Paint.Style.STROKE);l.setStrokeCap(Paint.Cap.ROUND);}
 public void setDemoMode(boolean e){demoMode=e;postInvalidateOnAnimation();}public void setDemoProgress(double s){route=(float)Math.max(0,s);postInvalidateOnAnimation();}public void setGroundProgress(double q,double hdg){groundProgress=(float)clamp((float)q,0,1);headingDeg=(float)hdg;postInvalidateOnAnimation();}public void setFlightState(double a,double s,boolean g,String ph){altitudeM=(float)Math.max(0,a);speedMps=(float)Math.max(0,s);onGround=g;phase=ph==null?"":ph;postInvalidateOnAnimation();}
 @Override protected void onDraw(Canvas c){long n=System.nanoTime();float dt=last==0?.016f:Math.min(.05f,(n-last)/1e9f);last=n;scroll=(scroll+speedMps*dt*.040f)%1f;if(phase.contains("TAKEOFF")||phase.contains("ROLLOUT"))runwayMeters+=speedMps*dt;if(phase.contains("HANGAR_START")||phase.contains("RUNWAY_HOLD"))runwayMeters=0;int w=getWidth(),h=getHeight();float hz=h*(.46f+.075f*Math.min(1,altitudeM/1300));sky(c,w,h,hz);if(phase.contains("HANGAR")){hangar(c,w,h,hz);return;}if(phase.contains("TAXI")){taxi(c,w,h,hz);animate();return;}if(demoMode&&phase.contains("ORBIT")){scenery(c,w,h,hz);animate();return;}runway(c,w,h,hz);animate();}
 private void animate(){if(speedMps>1)postInvalidateOnAnimation();}
 private void sky(Canvas c,int w,int h,float hz){f.setShader(new LinearGradient(0,0,0,hz,new int[]{0xff071624,0xff4b87a8,0xffc7dce6},null,Shader.TileMode.CLAMP));c.drawRect(0,0,w,hz,f);f.setShader(null);f.setShader(new LinearGradient(0,hz*.70f,0,hz,0x00ffffff,0x5aeaf1f2,Shader.TileMode.CLAMP));c.drawRect(0,hz*.68f,w,hz,f);f.setShader(null);for(int i=0;i<6;i++){float x=(w*(.06f+i*.19f)+(route*1.8f)%w)%w,y=hz*(.10f+(i%3)*.055f),ww=w*(.11f+(i%2)*.05f);f.setColor(0x22ffffff);c.drawOval(x,y,x+ww,y+hz*.030f,f);c.drawOval(x+ww*.18f,y-hz*.018f,x+ww*.64f,y+hz*.020f,f);} }
 private void hangar(Canvas c,int w,int h,float hz){float q=phase.contains("PARK")?1-groundProgress:groundProgress,cx=w*.5f,doorHalf=w*(.22f+.15f*q),top=h*.17f,bottom=h*.78f;f.setShader(new LinearGradient(0,0,0,h,new int[]{0xff0b1116,0xff182126,0xff32393d},null,Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,f);f.setShader(null);outside(c,cx-doorHalf,top,cx+doorHalf,bottom,w,h);quad(c,cx-doorHalf,bottom,cx+doorHalf,bottom,w,h,0,h,0xff343a3d);l.setColor(0xff626c71);for(int i=-8;i<=8;i++){float x=cx+i*w*.068f;c.drawLine(x,h,cx+(x-cx)*.28f,bottom,l);}for(int i=1;i<7;i++){float t=i/7f,y=lerp(bottom,h,t*t);c.drawLine(0,y,w,y,l);}l.setColor(0xffe5c52e);l.setStrokeWidth(5);c.drawLine(cx,bottom,cx,h,l);
  l.setColor(0xff667278);for(int i=0;i<6;i++){float t=i/5f,y=lerp(h*.07f,bottom,t),hh=lerp(w*.47f,doorHalf,t);l.setStrokeWidth(7-3*t);c.drawLine(cx-hh,y,cx-hh,bottom,l);c.drawLine(cx+hh,y,cx+hh,bottom,l);c.drawLine(cx-hh,y,cx+hh,y,l);c.drawLine(cx-hh,y,cx,y-h*.055f,l);c.drawLine(cx+hh,y,cx,y-h*.055f,l);}for(int i=0;i<8;i++){float x=w*(.11f+i*.105f);f.setColor(0x66ffe7a6);c.drawRoundRect(x,h*.075f,x+w*.055f,h*.092f,5,5,f);}for(int s=-1;s<=1;s+=2){float bx=s<0?w*.025f:w*.865f;f.setColor(0xff444d52);c.drawRect(bx,h*.50f,bx+w*.105f,h*.77f,f);f.setColor(0xff20272b);for(int k=0;k<4;k++)c.drawRect(bx+w*.012f,h*(.535f+k*.052f),bx+w*.093f,h*(.552f+k*.052f),f);f.setColor(0xffc93732);c.drawRect(bx+w*.014f,h*.69f,bx+w*.035f,h*.755f,f);}f.setColor(0xe8ffffff);f.setTextSize(Math.max(15,w*.016f));c.drawText("HANGAR 01  •  TAXI A  •  RWY 27",w*.035f,h*.93f,f);}
 private void outside(Canvas c,float x0,float y0,float x1,float y1,int w,int h){f.setShader(new LinearGradient(0,y0,0,y1,new int[]{0xff9dcfe2,0xff729ead,0xff4b6746},null,Shader.TileMode.CLAMP));c.drawRect(x0,y0,x1,y1,f);f.setShader(null);float cx=(x0+x1)/2;quad(c,cx-(x1-x0)*.06f,y0+(y1-y0)*.12f,cx+(x1-x0)*.06f,y0+(y1-y0)*.12f,x1,y1,x0,y1,0xff555b5d);l.setColor(0xffe8ca31);l.setStrokeWidth(4);c.drawLine(cx,y0+(y1-y0)*.12f,cx,y1,l);settlement(c,(int)x0,(int)x1,(int)(y0+(y1-y0)*.40f),(int)(y1-y0),.55f);}
 private void taxi(Canvas c,int w,int h,float hz){f.setColor(0xff445a40);c.drawRect(0,hz,w,h,f);mountains(c,w,h,hz,.17f,false);settlement(c,0,w,(int)hz,h,.72f);float cx=w*.5f,far=w*.042f,near=w*.29f;quad(c,cx-far,hz+h*.015f,cx+far,hz+h*.015f,cx+near,h,cx-near,h,0xff505658);quad(c,cx-far*.78f,hz+h*.015f,cx+far*.78f,hz+h*.015f,cx+near*.78f,h,cx-near*.78f,h,0xff3c4143);l.setColor(0xffefca22);l.setStrokeWidth(5);c.drawLine(cx,hz+h*.015f,cx,h,l);for(int i=0;i<24;i++){float q=(i/24f+scroll*.56f)%1f,z=q*q,y=lerp(hz+h*.025f,h,z),hh=lerp(far,near,z);f.setColor(0xff3e9af5);float r=1.2f+4*z;c.drawCircle(cx-hh*.94f,y,r,f);c.drawCircle(cx+hh*.94f,y,r,f);if(i%3==0){l.setColor(0x355f6465);l.setStrokeWidth(1+2*z);c.drawLine(cx-hh*.74f,y,cx+hh*.74f,y,l);}}if(groundProgress>.56f){float y=h*.66f,hh=w*.14f;l.setColor(0xffffd43e);l.setStrokeWidth(5);c.drawLine(cx-hh,y,cx+hh,y,l);l.setStrokeWidth(2);for(int i=0;i<8;i++){float x=cx-hh+i*(2*hh/7f);c.drawLine(x,y+7,x+10,y+18,l);}f.setColor(0xeeffffff);f.setTextSize(Math.max(14,w*.015f));c.drawText("RWY 27 HOLD SHORT",w*.68f,h*.72f,f);}f.setColor(0xe8ffffff);f.setTextSize(Math.max(14,w*.015f));c.drawText("HDG "+String.format(Locale.US,"%03.0f",norm(headingDeg))+"  •  TAXI",w*.04f,h*.92f,f);}
 private void runway(Canvas c,int w,int h,float hz){float near=1-Math.min(1,altitudeM/1050f),err=angleError(headingDeg,270f),cx=w*.5f+clamp(err/24f,-1,1)*w*.10f,fh=w*(.018f+.012f*near),nh=w*(onGround?.45f:(.12f+.30f*near)),fy=hz+h*.014f,ny=h*(onGround?.999f:(.72f+.26f*near));terrain(c,w,h,hz);quad(c,cx-fh*1.28f,fy,cx+fh*1.28f,fy,cx+nh*1.10f,ny,cx-nh*1.10f,ny,0xff70736f);quad(c,cx-fh,fy,cx+fh,fy,cx+nh,ny,cx-nh,ny,0xff282c2e);for(int i=-8;i<=8;i++){float a=i/8f;l.setColor(i%3==0?0x33484a4b:0x1d101112);l.setStrokeWidth(1+Math.abs(a)*1.2f);c.drawLine(cx+fh*a*.82f,fy,cx+nh*a*.82f,ny,l);}l.setColor(0xfff4f3ed);l.setStrokeWidth(Math.max(2,w*.0025f));c.drawLine(cx-fh,fy,cx-nh,ny,l);c.drawLine(cx+fh,fy,cx+nh,ny,l);for(int i=0;i<34;i++){float q=(i/34f+scroll)%1f,z=q*q,y=lerp(fy,ny,z),y2=Math.min(ny,y+4+44*z);l.setStrokeWidth(2+12*z);c.drawLine(cx,y,cx,y2,l);}for(int i=0;i<30;i++){float q=(i/30f+scroll*.62f)%1f,z=q*q,y=lerp(fy,ny,z),hh=lerp(fh,nh,z);f.setColor(i>25?0xffffd56b:0xfff3f0d8);float r=1+4*z;c.drawCircle(cx-hh,y,r,f);c.drawCircle(cx+hh,y,r,f);}float ap=(.46f+scroll*.11f)%1f,az=ap*ap,ay=lerp(fy,ny,az),ah=lerp(fh,nh,az);f.setColor(0xfff4f4ef);c.drawRect(cx-ah*.62f,ay,cx-ah*.38f,ay+12+32*az,f);c.drawRect(cx+ah*.38f,ay,cx+ah*.62f,ay+12+32*az,f);float nz=.49f+(phase.contains("TAKEOFF")?runwayMeters/300f:0);if(nz<=1.04f){float z=clamp(nz,0,1),y=lerp(fy,ny,z*z),hh=lerp(fh,nh,z);for(int i=-5;i<=5;i++){if(i==0)continue;float x=cx+i*hh*.095f;c.drawRect(x-hh*.030f,y,x+hh*.030f,y+13+38*z,f);}f.setTextAlign(Paint.Align.CENTER);f.setTextSize(Math.max(27,w*(.033f+.030f*z)));c.drawText("27",cx,y+58+42*z,f);f.setTextAlign(Paint.Align.LEFT);}if(!onGround||phase.contains("APPROACH")||phase.contains("FLARE")){float py=lerp(fy,ny,.36f),ph=lerp(fh,nh,.36f);for(int i=0;i<4;i++){f.setColor(i<2?0xffffffff:0xffff3b30);c.drawCircle(cx-ph*1.28f+i*6,py,3.2f,f);}}if(phase.contains("APPROACH")||phase.contains("FLARE")){f.setColor(Math.abs(err)<2.5?0xff7fe889:0xffffd35a);f.setTextSize(Math.max(14,w*.015f));c.drawText(Math.abs(err)<2.5?"RWY 27 • CENTERLINE CAPTURED":"RWY 27 • ALIGNING",w*.67f,h*.92f,f);}}
 private void terrain(Canvas c,int w,int h,float hz){f.setColor(0xff38513a);c.drawRect(0,hz,w,h,f);mountains(c,w,h,hz,.23f,false);settlement(c,0,w,(int)hz,h,.55f);}
 private void settlement(Canvas c,int x0,int x1,int baseY,int h,float density){int span=Math.max(1,x1-x0),count=Math.max(5,(int)(span/72f*density));for(int i=0;i<count;i++){float seed=(i*37%101)/101f,x=x0+span*(.035f+(i+.4f)/count*.93f),bw=Math.max(14,span*(.025f+.015f*((i*11)%5)/4f)),bh=h*(.035f+.035f*((i*7)%5)/4f),ground=baseY-2-(i%3)*2;int wall=i%4==0?0xffd5c7ad:i%4==1?0xffc0b49e:i%4==2?0xffaab0ad:0xffb89e83;f.setColor(0x33000000);c.drawRect(x+4,ground-bh+4,x+bw+6,ground+4,f);f.setColor(wall);c.drawRect(x,ground-bh,x+bw,ground,f);p.reset();p.moveTo(x-2,ground-bh);p.lineTo(x+bw*.5f,ground-bh-h*.020f*(.65f+seed));p.lineTo(x+bw+2,ground-bh);p.close();f.setColor(i%2==0?0xff7b3d32:0xff55595a);c.drawPath(p,f);f.setColor(0xff6b8da0);int floors=bh>h*.055f?2:1;for(int r=0;r<floors;r++)for(int k=0;k<2;k++){float wx=x+bw*(.18f+k*.45f),wy=ground-bh+h*.013f+r*h*.022f;c.drawRect(wx,wy,wx+bw*.15f,wy+h*.010f,f);}f.setColor(0xff51483e);c.drawRect(x+bw*.43f,ground-h*.020f,x+bw*.58f,ground,f);if(i%4==0){f.setColor(0xff3b613e);c.drawCircle(x-bw*.16f,ground-h*.012f,bw*.18f,f);c.drawRect(x-bw*.18f,ground-h*.010f,x-bw*.14f,ground,f);}}}
 private void scenery(Canvas c,int w,int h,float hz){float t=Math.min(300,route);if(t<45){departureCoast(c,w,h,hz,t/45f);label(c,w,h,"KIYIYA TIRMANIŞ");}else if(t<95){mountains(c,w,h,hz,.58f,false);label(c,w,h,"DAĞLARA YAKLAŞMA");}else if(t<150){mountains(c,w,h,hz,.82f,true);label(c,w,h,"VADİ İÇİ UÇUŞ");}else if(t<210){mountains(c,w,h,hz,.96f,true);road(c,w,h,hz);label(c,w,h,"DAĞ YOLU TAKİBİ");}else if(t<255){lake(c,w,h,hz);label(c,w,h,"GÖL / KIYI GEÇİŞİ");}else if(t<280){mountains(c,w,h,hz,.75f,false);label(c,w,h,"YÜKSEK ARAZİ");}else{mountains(c,w,h,hz,.34f,false);terrain(c,w,h,hz);label(c,w,h,"RWY 27 İÇİN HİZALANMA");}}
 private void departureCoast(Canvas c,int w,int h,float hz,float t){float shore=hz+h*(.055f+.045f*t);mountains(c,w,h,hz,.20f+.13f*t,false);f.setColor(0xff405a3d);p.reset();p.moveTo(0,shore);for(int i=0;i<=12;i++){float x=w*i/12f,y=shore+h*.025f*(float)Math.sin(i*.9+route*.03);p.lineTo(x,y);}p.lineTo(w,h);p.lineTo(0,h);p.close();c.drawPath(p,f);settlement(c,0,w,(int)(shore+h*.02f),h,.42f);water(c,w,h,shore+h*.065f);}
 private void water(Canvas c,int w,int h,float top){f.setShader(new LinearGradient(0,top,0,h,new int[]{0xff4f9fba,0xff17617d,0xff082d45},null,Shader.TileMode.CLAMP));c.drawRect(0,top,w,h,f);f.setShader(null);float motion=route*11f+scroll*w*.9f;for(int i=0;i<58;i++){float z=((i*37)%100)/100f,y=top+(h-top)*(.05f+.90f*z),x=(i*113+motion*(.25f+z))%Math.max(1,w);float ww=12+w*.026f*z,hh=1.2f+2.7f*z;f.setColor(i%5==0?0x55ffffff:0x297bd0e4);c.drawOval(x,y,x+ww,y+hh,f);}f.setShader(new LinearGradient(w*.24f,top,w*.72f,h,0x00ffffff,0x24ffffff,Shader.TileMode.CLAMP));c.drawRect(w*.24f,top,w*.72f,h,f);f.setShader(null);}
 private void mountains(Canvas c,int w,int h,float hz,float scale,boolean valley){mountainLayer(c,w,h,hz,scale*.55f,0xff71868a,1.12f,valley);mountainLayer(c,w,h,hz,scale*.76f,0xff526a63,1.38f,valley);mountainLayer(c,w,h,hz,scale,0xff30483d,1.67f,valley);}
 private void mountainLayer(Canvas c,int w,int h,float hz,float scale,int col,float freq,boolean valley){p.reset();p.moveTo(0,h);for(int i=0;i<=22;i++){float x=w*i/22f,y=hz-h*scale*(.035f+.13f*(float)Math.abs(Math.sin(i*freq+route*.010)));if(valley&&i>9&&i<13)y+=h*.12f;p.lineTo(x,y);}p.lineTo(w,h);p.close();f.setColor(col);c.drawPath(p,f);}
 private void lake(Canvas c,int w,int h,float hz){mountains(c,w,h,hz,.56f,true);water(c,w,h,hz+h*.12f);}private void road(Canvas c,int w,int h,float hz){l.setColor(0xff737876);l.setStrokeWidth(Math.max(12,w*.018f));p.reset();p.moveTo(w*.10f,h);p.cubicTo(w*.38f,h*.72f,w*.32f,h*.60f,w*.61f,hz+h*.06f);c.drawPath(p,l);l.setColor(0xffe8d15a);l.setStrokeWidth(2);c.drawPath(p,l);}private void label(Canvas c,int w,int h,String s){f.setColor(0xe8ffffff);f.setTextSize(Math.max(19,w*.020f));c.drawText(s,w*.04f,h*.89f,f);}
 private void quad(Canvas c,float x1,float y1,float x2,float y2,float x3,float y3,float x4,float y4,int col){p.reset();p.moveTo(x1,y1);p.lineTo(x2,y2);p.lineTo(x3,y3);p.lineTo(x4,y4);p.close();f.setColor(col);c.drawPath(p,f);}private static float norm(float a){a%=360;if(a<0)a+=360;return a;}private static float angleError(float h,float t){float d=t-h;while(d>180)d-=360;while(d<-180)d+=360;return d;}private static float clamp(float v,float lo,float hi){return Math.max(lo,Math.min(hi,v));}private static float lerp(float a,float b,float t){return a+(b-a)*t;}
}
